+// A count off a merged word map, or null where the window folded no day at all. The
+// difference matters: a folded week with no parks is `0` parks, an unfolded one is
+// `null`, and only the first is a fact about the machinery.
+const countOf = (window, group, word) =>
+  (window.foldedDays ? (window[group][word] ?? 0) : null);
