+  const members = folding
+    .map((r) => ({ repo: r.repo, machine: tasksMachine(r.tasksUsage, { now, span }) }))
+    .sort((a, b) => (b.machine.cost.current.runs ?? -1) - (a.machine.cost.current.runs ?? -1)
+      || a.repo.localeCompare(b.repo));
