2	// nothing else: the member's own `tasks-usage.GENERATED.json`. Pure, like every
3	// derive module here: no clock of its own beyond the one it is handed, no I/O, no DOM.
4	//
5	// THE SESSIONS' PLANE IS NOT THIS ONE. `growthSeries` and `fleetCorpus` answer what the
6	// corpus did to the sessions; this answers what the scheduler and the executor did, and
7	// the two files are folded by two tasks on two watermarks. A member folding one and not
8	// the other is an ordinary state, so nothing here falls back to the other file — it
9	// says the machinery plane is unfolded and stops.
10	//
11	// NOTHING HERE IMPORTS THE FOLD, and nothing here names the file's vocabulary as a
12	// list of its own: the decode in `read/usage.mjs` expands each positional tuple against
13	// the header the file declares, and this module reads the named result. A counter added
14	// or retired on the writing side reaches the panel with no change here.
15	//
16	// THE THREE RULES THE PANEL RENDERS UNDER, enforced at this layer rather than at the
17	// render, so no caller can forget one:
18	//
19	//   A WINDOW AGAINST THE WINDOW BEFORE IT, never a cumulative total. Every figure this
20	//   returns is a pair, `current` and `previous`, over two adjacent equal spans.
21	//
22	//   A MISSING KEY IS *NOT RECORDED*, never zero. A sum is taken over the days that had
23	//   an opinion and is `null` when none did — which is a different fact from `0`, and the
24	//   one the whole positional-tuple format exists to keep. `sum` below is the only place
25	//   that rule is implemented.
26	//
27	//   AN UNFOLDED MEMBER IS NAMED AND COUNTED IN NOTHING. `fleetTasksMachine` splits the
28	//   readable members into those that fold this file and those that do not, and the
29	//   second list is a census, never a row of zeroes in the first.
30	
31	const DAY_MS = 86400e3;
32	
33	const dayKey = (t) => new Date(t).toISOString().slice(0, 10);
34	
35	// A sum over the entries that HAD an opinion, or null when none did. The unknown-is-not-
36	// zero rule in one function, so no caller has to remember it.
37	const sum = (values) => {
38	  const known = values.filter((n) => typeof n === 'number');
39	  return known.length ? known.reduce((a, b) => a + b, 0) : null;
40	};
41	
42	// The outcome and park vocabularies the queue already spells its labels in. Named here
43	// only to give the panel a stable COLUMN ORDER — a word the file carries that is not in
44	// either list is still counted, under `other`, rather than dropped.
45	export const OUTCOMES = ['done', 'delivered', 'obsolete', 'none'];
46	export const PARKS = ['failure', 'action', 'decision', 'approval'];
47	
48	// The four latency slots, in the order an item passes through them. Each is a SAMPLE
49	// list in the file — never a quantile — because a week's p50 is not derivable from its
50	// days', so the quantile is taken here, over whatever window is being drawn.
51	export const LATENCIES = [
52	  { key: 'tickToItemMinutes', label: 'tick → item' },
53	  { key: 'itemToPickMinutes', label: 'item → pick' },
54	  { key: 'pickToHandOffMinutes', label: 'pick → hand-off' },
55	  { key: 'handOffToConvergeMinutes', label: 'hand-off → converge' },
56	];
57	
58	// What the panel would draw if the file carried it, and does not. NOT a gap in this
59	// module — a gap in the source — so it is stated in the panel's own note rather than
60	// drawn as an empty series or, worse, a zero. Adding a counter to the file is the
61	// fold's change to make and not this panel's, so these stay named until it does.
62	export const UNRECORDED = [
63	  'janitor repairs — the fold counts a task\'s outcomes and parks, not which of them the janitor rewrote',
64	  'leash reclaims — an item reclaimed from a dead episode is folded as its eventual outcome, with no separate count',
65	];
66	
67	// Nearest-rank p50 and p90 over the samples handed in, plus how many there were. Fewer
68	// than two samples is reported as a count with no quantile: a p90 over one measurement
69	// is that measurement wearing a statistic's name.
70	export function quantiles(samples) {
71	  const xs = samples.filter((n) => typeof n === 'number').sort((a, b) => a - b);
72	  if (!xs.length) return { n: 0, p50: null, p90: null, max: null };
73	  const at = (q) => xs[Math.min(xs.length - 1, Math.ceil(q * xs.length) - 1)];
74	  return {
75	    n: xs.length,
76	    p50: xs.length >= 2 ? at(0.5) : null,
77	    p90: xs.length >= 2 ? at(0.9) : null,
78	    max: xs[xs.length - 1],
79	  };
80	}
81	
82	// The day keys of the two adjacent windows ending today, as `[current, previous]`. Both
83	// are half-open on the right in the same direction, so a day belongs to exactly one.
84	export function windowDays(now, span) {
85	  const today = Math.floor(now / DAY_MS) * DAY_MS;
86	  const keys = (endExclusive) => Array.from({ length: span }, (_, i) =>
87	    dayKey(endExclusive - (span - i) * DAY_MS));
88	  return [keys(today + DAY_MS), keys(today + DAY_MS - span * DAY_MS)];
89	}
90	
91	// --- one window, folded out of the day rows -----------------------------------------
92	
93	// Everything one window has to say, from the day rows it covers. `rows` is already the
