attachment.snippet:
1	// The machinery panel, drawn. One renderer for both pages: the repo page draws it for
2	// one member and the fleet page draws the roll-up, and they are the same shapes — which
3	// is why this is its own module rather than two copies that drift.
4	//
5	// WHAT IT DRAWS, AND WHAT IT REFUSES TO.
6	//
7	// Every figure is a WINDOW AGAINST THE WINDOW BEFORE IT, because a cumulative total is
8	// a number a person reads as a report card and nothing measures. `windowFigure` is the
9	// page's own primitive for that and spells the previous figure out beside the arrow.
10	//
11	// A MISSING KEY IS *NOT RECORDED*. The derivation already answers null for a counter no
12	// day had an opinion on; `fmt` below renders that as an em dash and the note beside the
13	// tile says which source did not answer. Nothing here coerces a null to zero, and the
14	// one place a zero appears is where the window WAS folded and the word did not occur.
15	//
16	// ONE SCALE PER CHART. Two measures of different magnitudes get two charts, never two
17	// y-axes on one — so runs and closes are drawn separately rather than superimposed.
18	//
19	// PARKS AND LATENCIES ARE TABLES, not charts. The park kinds carry severity, and the
20	// page's status palette is reserved for severity; painting four park kinds as four
21	// categorical series would spend it on identity. A ruled table says the same thing and
22	// is also the table view the contrast rule obliges for the lighter series colours.
23	
24	import {
25	  el, chartLegend, stackedColumns, windowFigure, emptyRow, OUTCOME_COLOR,
26	} from './ui.mjs';
27	import { detailTable, expander } from './sheet.mjs';
28	import { OUTCOMES, PARKS, LATENCIES, change } from '../derive/tasks-machine.mjs';
29	
30	// A figure, or the em dash that means nobody recorded it. Never a zero standing in for
31	// an unknown — the distinction this whole panel exists to keep.
32	export const fmt = (n) => (typeof n === 'number' ? n.toLocaleString() : '—');
33	
34	// Minutes as a person reads them. Under an hour stays minutes, because the latencies
35	// this panel reports are mostly single-digit and "0.1h" says less than "6m".
36	export const mins = (n) => {
37	  if (typeof n !== 'number') return '—';
38	  if (n < 60) return `${Math.round(n)}m`;
39	  if (n < 1440) return `${Math.round(n / 6) / 10}h`;
40	  return `${Math.round(n / 144) / 10}d`;
41	};
42	
43	const money = (n, rate) => (typeof n === 'number' && typeof rate === 'number'
44	  ? `$${(n).toFixed(2)}`
45	  : null);
46	
47	// The outcome words, in the colours the rest of the page already gives them. Colour
48	// follows the entity: `done` is the same green in this chart as in the queue panel
49	// above it, so the two read as one vocabulary and not two.
50	const OUTCOME_SERIES = [
51	  { label: 'done', color: OUTCOME_COLOR.done, value: (d) => d.done },
52	  { label: 'delivered', color: OUTCOME_COLOR.delivered, value: (d) => d.delivered },
53	  { label: 'obsolete', color: OUTCOME_COLOR.obsolete, value: (d) => d.obsolete },
54	  { label: 'no outcome', color: OUTCOME_COLOR.none, value: (d) => d.none },
55	];
56	
57	const RUN_SERIES = [{ label: 'workflow runs', color: 'var(--s-blue)', value: (d) => d.runs }];
58	
59	// The sentence every panel opens with: which two spans are being compared, and how much
60	// of them the file actually carried. A rate with an unstated denominator is the figure
61	// this panel exists not to print.
62	export function windowNote(m) {
63	  const span = `${m.from} → ${m.to}`;
64	  const before = `${m.previousFrom} → ${m.previousTo}`;
65	  const folded = m.foldedDays
66	    ? ` · ${m.foldedDays.current}/${m.span} day(s) folded this window, ${m.foldedDays.previous}/${m.span} before`
