+const file = (days, over = {}) => decodeTasksUsage({
+  version: 1,
+  generated: '2026-09-15T13:18:16.932Z',
+  foldedThrough: '2026-09-15',
+  minuteRate: null,
+  fields: FIELDS,
+  days,
+  hours: {},
+  weeks: {},
+  ...over,
+});
+
+// Two folded days in each window, and the days between them absent from the file
